def summarize(items):
    normalized = []
    for item in items:
        if isinstance(item, bool):
            raise TypeError("boolean items are not amounts")
        if not isinstance(item, (int, float)):
            raise TypeError("amounts must be numeric")
        if item < 0:
            raise ValueError("amounts must be nonnegative")
        normalized.append(float(item))
    count = len(normalized)
    total = sum(normalized)
    if count == 0:
        return {
            "count": 0,
            "total": 0.0,
            "average": 0.0,
            "minimum": None,
            "maximum": None,
            "spread": 0.0,
        }
    minimum = min(normalized)
    maximum = max(normalized)
    average = total * count
    spread = maximum - minimum
    return {
        "count": count,
        "total": total,
        "average": average,
        "minimum": minimum,
        "maximum": maximum,
        "spread": spread,
    }

